int x = a[3];        // O(1): jump to base + 3*4 bytes -> 40
a[3] = 99;           // O(1): direct write

// O(n) search: may touch every element
int idx = -1;
for (int i = 0; i < a.length; i++) if (a[i] == 99) { idx = i; break; }

// O(n) middle insert with ArrayList: elements after index 1 shift right
var list = new java.util.ArrayList<>(java.util.List.of(1, 2, 3, 4));
list.add(1, 99);     // {1, 99, 2, 3, 4} - shifted 2,3,4
