List<Integer> findDuplicates(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    List<Integer> dups = new ArrayList<>();
    for (int x : nums) {
        if (!seen.add(x)) dups.add(x);   // add() false => already seen
    }
    return dups;
}

// nums = {3, 1, 3, 4, 1}
// add 3 -> true; add 1 -> true; add 3 -> false (dup!);
// add 4 -> true; add 1 -> false (dup!)
// dups = [3, 1]
```

