boolean isAnagram(String a, String b) {
    if (a.length() != b.length()) return false;   // early exit
    int[] count = new int[26];
    for (int i = 0; i < a.length(); i++) {
        count[a.charAt(i) - 'a']++;   // count first string up
        count[b.charAt(i) - 'a']--;   // count second string down
    }
    for (int c : count) if (c != 0) return false;
    return true;
}

// a="listen", b="silent"
// after loop every bucket nets to 0 -> true
// a="rat", b="car": 'r','a' net 0 but 't'=+1,'c'=-1 -> false
```

