int[] pairSum(int[] nums, int target) {   // nums must be sorted
    int left = 0, right = nums.length - 1;
    while (left < right) {
        int sum = nums[left] + nums[right];
        if (sum == target) return new int[]{left, right};
        else if (sum < target) left++;    // grow the sum
        else right--;                     // shrink the sum
    }
    return new int[]{-1, -1};
}

// nums = {1, 3, 4, 6, 8}, target = 10
// 1+8=9 <10 -> left++; 3+8=11 >10 -> right--; 3+6=9 <10 -> left++; 4+6=10 -> [2,3]
```

