int maxSubArray(int[] nums) {
    int cur = nums[0], best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        cur = Math.max(nums[i], cur + nums[i]);  // extend or restart
        best = Math.max(best, cur);              // track global best
    }
    return best;
}

// nums = {-2, 1, -3, 4, -1, 2, 1}
// cur: -2,1,-2,4,3,5,6  (restart at index1 and index3)
// best: -2,1,1,4,4,5,6 -> answer 6  (subarray {4,-1,2,1})
```
